    }
    *out = a * b;
    return true;
}

inline unsigned int choose_block_size(size_t n) {
    unsigned int block = 1u;
    while (block < n && block < kMaxBlockSize) {
        block <<= 1u;
    }
    if (block > kMaxBlockSize) {
        block = kMaxBlockSize;
    }
    return block;
}

inline bool valid_eps(float eps) {
    return std::isfinite(eps) && eps > 0.0f;
}

cudaError_t validate_current_device_limits(size_t grid_x, unsigned int block_x) {
    int device = 0;
