        }
    }
    return value;
}

__device__ __forceinline__ float warp_reduce_max(float value) {
    const unsigned int mask = __activemask();
    const unsigned int lane = threadIdx.x & (kWarpSize - 1u);
    const unsigned int active = __popc(mask);
    for (int offset = static_cast<int>(kWarpSize / 2u); offset > 0; offset >>= 1) {
        const float other = __shfl_down_sync(mask, value, offset);
        if (lane + static_cast<unsigned int>(offset) < active) {
            value = fmaxf(value, other);
        }
    }
    return value;
}

__device__ __forceinline__ WelfordData welford_update(WelfordData acc, float x) {
    acc.count += 1u;
    const float delta = x - acc.mean;
    acc.mean += delta / static_cast<float>(acc.count);
    const float delta2 = x - acc.mean;
    acc.m2 += delta * delta2;
    return acc;
}

__device__ __forceinline__ WelfordData welford_combine(WelfordData a, WelfordData b) {
    if (a.count == 0u) {
        return b;
    }
    if (b.count == 0u) {
        return a;
    }
    const float a_count = static_cast<float>(a.count);
    const float b_count = static_cast<float>(b.count);
    const float total = a_count + b_count;
    const float delta = b.mean - a.mean;
    WelfordData out;
    out.mean = a.mean + delta * (b_count / total);
    out.m2 = a.m2 + b.m2 + delta * delta * (a_count * b_count / total);
    out.count = a.count + b.count;
    return out;
}

__device__ __forceinline__ WelfordData warp_reduce_welford(WelfordData value) {
    const unsigned int mask = __activemask();
    const unsigned int lane = threadIdx.x & (kWarpSize - 1u);
    const unsigned int active = __popc(mask);
    for (int offset = static_cast<int>(kWarpSize / 2u); offset > 0; offset >>= 1) {
        WelfordData other;
        other.mean = __shfl_down_sync(mask, value.mean, offset);
        other.m2 = __shfl_down_sync(mask, value.m2, offset);
        other.count = __shfl_down_sync(mask, value.count, offset);
        if (lane + static_cast<unsigned int>(offset) < active) {
            value = welford_combine(value, other);
        }
    }
    return value;
}

__device__ __forceinline__ float block_reduce_sum(float value, float* shared) {
    const unsigned int tid = threadIdx.x;
    const unsigned int lane = tid & (kWarpSize - 1u);
    const unsigned int wid = tid >> 5u;
    const unsigned int num_warps = (blockDim.x + kWarpSize - 1u) >> 5u;
    value = warp_reduce_sum(value);
    if (lane == 0u) {
        shared[wid] = value;
    }
    __syncthreads();
    float result = 0.0f;
    if (wid == 0u) {
        result = lane < num_warps ? shared[lane] : 0.0f;
        result = warp_reduce_sum(result);
    }
    if (tid == 0u) {
        shared[0] = result;
    }
    __syncthreads();
    return shared[0];
}

__device__ __forceinline__ unsigned int block_reduce_sum_u32(unsigned int value, unsigned int* shared) {
    const unsigned int tid = threadIdx.x;
    const unsigned int lane = tid & (kWarpSize - 1u);
    const unsigned int wid = tid >> 5u;
    const unsigned int num_warps = (blockDim.x + kWarpSize - 1u) >> 5u;
    value = warp_reduce_sum_u32(value);
    if (lane == 0u) {
        shared[wid] = value;
    }
    __syncthreads();
    unsigned int result = 0u;
    if (wid == 0u) {
        result = lane < num_warps ? shared[lane] : 0u;
        result = warp_reduce_sum_u32(result);
    }
    if (tid == 0u) {
        shared[0] = result;
    }
    __syncthreads();
    return shared[0];
}

__device__ __forceinline__ float block_reduce_max(float value, float* shared) {
    const unsigned int tid = threadIdx.x;
    const unsigned int lane = tid & (kWarpSize - 1u);
    const unsigned int wid = tid >> 5u;
    const unsigned int num_warps = (blockDim.x + kWarpSize - 1u) >> 5u;
    value = warp_reduce_max(value);
    if (lane == 0u) {
        shared[wid] = value;
    }
    __syncthreads();
    float result = -CUDART_INF_F;
    if (wid == 0u) {
        result = lane < num_warps ? shared[lane] : -CUDART_INF_F;
        result = warp_reduce_max(result);
    }
    if (tid == 0u) {
        shared[0] = result;
    }
    __syncthreads();
    return shared[0];
}

__device__ __forceinline__ WelfordData block_reduce_welford(WelfordData value, WelfordData* shared) {
    const unsigned int tid = threadIdx.x;
    const unsigned int lane = tid & (kWarpSize - 1u);
    const unsigned int wid = tid >> 5u;
    const unsigned int num_warps = (blockDim.x + kWarpSize - 1u) >> 5u;
    value = warp_reduce_welford(value);
    if (lane == 0u) {
        shared[wid] = value;
    }
    __syncthreads();
    WelfordData result{0.0f, 0.0f, 0u};
    if (wid == 0u) {
        result = lane < num_warps ? shared[lane] : WelfordData{0.0f, 0.0f, 0u};
        result = warp_reduce_welford(result);
    }
    if (tid == 0u) {
        shared[0] = result;
    }
    __syncthreads();
    return shared[0];
}

__device__ __forceinline__ float gelu_approximate(float x) {
    const float x2 = x * x;
    const float x3 = x * x2;
    const float u = kSqrt2OverPi * (x + kGeluCoeff * x3);
    return 0.5f * x * (1.0f + tanhf(u));
}

__device__ __forceinline__ float gelu_exact(float x) {
    return 0.5f * x * (1.0f + erff(x * kInvSqrt2));
}

__global__ void rmsnorm_forward_kernel(
    const __nv_bfloat16* __restrict__ input,
    const __nv_bfloat16* __restrict__ weight,
    __nv_bfloat16* __restrict__ output,
    uint32_t n_rows,
    uint32_t normalized_shape,
    float eps
) {
    const uint32_t row = blockIdx.x;
    if (row >= n_rows) {
        return;
    }

    const size_t base = static_cast<size_t>(row) * static_cast<size_t>(normalized_shape);
    __shared__ float shared[32];

    float sum_sq_local = 0.0f;
    for (uint32_t i = threadIdx.x; i < normalized_shape; i += blockDim.x) {
        const float x = bf16_to_float(input, base + i);
        sum_sq_local = fmaf(x, x, sum_sq_local);
    }

    const float sum_sq = block_reduce_sum(sum_sq_local, shared);
    const float inv_rms = rsqrtf(sum_sq / static_cast<float>(normalized_shape) + eps);

    for (uint32_t i = threadIdx.x; i < normalized_shape; i += blockDim.x) {
        const float x = bf16_to_float(input, base + i);
        const float w = load_weight_or_one(weight, i);
        output[base + i] = float_to_bf16(x * inv_rms * w);
    }
}

__global__ void rmsnorm_stats_kernel(
    const __nv_bfloat16* __restrict__ input,
    float* __restrict__ inv_rms,
    uint32_t n_rows,
    uint32_t normalized_shape,
    float eps
) {
    const uint32_t row = blockIdx.x;
    if (row >= n_rows) {
        return;
    }

    const size_t base = static_cast<size_t>(row) * static_cast<size_t>(normalized_shape);
    __shared__ float shared[32];

    float sum_sq_local = 0.0f;
    for (uint32_t i = threadIdx.x; i < normalized_shape; i += blockDim.x) {
        const float x = bf16_to_float(input, base + i);
        sum_sq_local = fmaf(x, x, sum_sq_local);
    }

    const float sum_sq = block_reduce_sum(sum_sq_local, shared);
    if (threadIdx.x == 0u) {
        inv_rms[row] = rsqrtf(sum_sq / static_cast<float>(normalized_shape) + eps);
    }
}

__global__ void rmsnorm_backward_input_kernel(
    const __nv_bfloat16* __restrict__ grad_output,
    const __nv_bfloat16* __restrict__ input,
    const __nv_bfloat16* __restrict__ weight,
    const float* __restrict__ inv_rms,
    __nv_bfloat16* __restrict__ grad_input,
    uint32_t n_rows,
    uint32_t normalized_shape
) {
    const uint32_t row = blockIdx.x;
    if (row >= n_rows) {
        return;
    }

    const size_t base = static_cast<size_t>(row) * static_cast<size_t>(normalized_shape);
    __shared__ float shared[32];

    float dot_local = 0.0f;
    for (uint32_t i = threadIdx.x; i < normalized_shape; i += blockDim.x) {
        const float g = bf16_to_float(grad_output, base + i);
        const float w = load_weight_or_one(weight, i);
        const float x = bf16_to_float(input, base + i);
        dot_local += g * w * x;
    }

    const float dot = block_reduce_sum(dot_local, shared);
    const float inv = inv_rms[row];
    const float coeff = dot * inv * inv * inv / static_cast<float>(normalized_shape);

    for (uint32_t i = threadIdx.x; i < normalized_shape; i += blockDim.x) {
        const float g = bf16_to_float(grad_output, base + i);
        const float w = load_weight_or_one(weight, i);
        const float x = bf16_to_float(input, base + i);
        grad_input[base + i] = float_to_bf16(g * w * inv - x * coeff);
    }
}

__global__ void rmsnorm_backward_weight_kernel(
    const __nv_bfloat16* __restrict__ grad_output,
    const __nv_bfloat16* __restrict__ input,
    const float* __restrict__ inv_rms,
    float* __restrict__ grad_weight,
    uint32_t n_rows,
    uint32_t normalized_shape
) {
    const uint32_t col = blockIdx.x;
    if (col >= normalized_shape) {
        return;
    }

    __shared__ float shared[32];
    float acc_local = 0.0f;

    for (uint32_t row = threadIdx.x; row < n_rows; row += blockDim.x) {
        const size_t idx = static_cast<size_t>(row) * static_cast<size_t>(normalized_shape) + static_cast<size_t>(col);
        const float g = bf16_to_float(grad_output, idx);
        const float x = bf16_to_float(input, idx);
        acc_local += g * x * inv_rms[row];
    }

    const float total = block_reduce_sum(acc_local, shared);
    if (threadIdx.x == 0u) {
        grad_weight[col] = total;
    }
}

__global__ void float_to_bfloat16_kernel(
    const float* __restrict__ input,
    __nv_bfloat16* __restrict__ output,
    uint32_t numel
) {
    const uint32_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= numel) {
        return;
    }
    output[idx] = float_to_bf16(input[idx]);
}

__global__ void layernorm_forward_kernel(
    const __nv_bfloat16* __restrict__ input,
    const __nv_bfloat16* __restrict__ weight,
    const __nv_bfloat16* __restrict__ bias,
    __nv_bfloat16* __restrict__ output,
    uint32_t n_rows,
    uint32_t normalized_shape,
    float eps
) {
    const uint32_t row = blockIdx.x;
    if (row >= n_rows) {
        return;
    }

    const size_t base = static_cast<size_t>(row) * static_cast<size_t>(normalized_shape);
    __shared__ WelfordData shared[32];

    WelfordData acc{0.0f, 0.0f, 0u};
    for (uint32_t i = threadIdx.x; i < normalized_shape; i += blockDim.x) {
        acc = welford_update(acc, bf16_to_float(input, base + i));
    }

    const WelfordData stats = block_reduce_welford(acc, shared);
    const float mean = stats.mean;
    const float variance = stats.count == 0u ? 0.0f : stats.m2 / static_cast<float>(normalized_shape);
    const float inv_std = rsqrtf(variance + eps);

    for (uint32_t i = threadIdx.x; i < normalized_shape; i += blockDim.x) {
        const float x = bf16_to_float(input, base + i);
        const float w = load_weight_or_one(weight, i);
        const float b = load_bias_or_zero(bias, i);
        output[base + i] = float_to_bf16(fmaf((x - mean) * inv_std, w, b));
    }
}

__global__ void gelu_forward_kernel(
    const __nv_bfloat16* __restrict__ input,
    __nv_bfloat16* __restrict__ output,
    uint32_t numel,
    bool approximate
) {
    const uint32_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= numel) {
        return;
    }

    const float x = __bfloat162float(input[idx]);
    const float y = approximate ? gelu_approximate(x) : gelu_exact(x);
    output[idx] = float_to_bf16(y);
}

__global__ void gelu_backward_kernel(
    const __nv_bfloat16* __restrict__ grad_output,
    const __nv_bfloat16* __restrict__ input,
    __nv_bfloat16* __restrict__ grad_input,
    uint32_t numel,
    bool approximate
) {
    const uint32_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= numel) {
        return;
    }

    const float x = __bfloat162float(input[idx]);
    const float g = __bfloat162float(grad_output[idx]);

    float grad = 0.0f;
    if (approximate) {
        const float x2 = x * x;
        const float x3 = x * x2;
        const float u = kSqrt2OverPi * (x + kGeluCoeff * x3);
        const float t = tanhf(u);
        const float sech2 = 1.0f - t * t;
        const float du = kSqrt2OverPi * (1.0f + 3.0f * kGeluCoeff * x2);
        grad = 0.5f * (1.0f + t) + 0.5f * x * sech2 * du;
    } else {
        const float cdf = 0.5f * (1.0f + erff(x * kInvSqrt2));
        const float pdf = kInvSqrt2Pi * expf(-0.5f * x * x);
        grad = cdf + x * pdf;
    }

    grad_input[idx] = float_to_bf16(g * grad);
}

__global__ void softmax_forward_kernel(
    const __nv_bfloat16* __restrict__ input,
    __nv_bfloat16* __restrict__ output,
    uint32_t outer_size,
    uint32_t dim_size,
    uint32_t inner_size
) {
    const uint32_t row = blockIdx.x;
    const uint32_t total_rows = outer_size * inner_size;
    if (row >= total_rows) {
        return;
    }

    const uint32_t outer_idx = row / inner_size;
    const uint32_t inner_idx = row - outer_idx * inner_size;
    const size_t row_base = static_cast<size_t>(outer_idx) * static_cast<size_t>(dim_size) * static_cast<size_t>(inner_size) + static_cast<size_t>(inner_idx);

    __shared__ float shared_float[32];
    __shared__ unsigned int shared_uint[32];

    float local_max = -CUDART_INF_F;
    for (uint32_t i = threadIdx.x; i < dim_size; i += blockDim.x) {
        const float v = bf16_to_float(input, row_base + static_cast<size_t>(i) * static_cast<size_t>(inner_size));
        if (!isnan(v)) {
            local_max = fmaxf(local_max, v);
        }
    }

    const float max_val = block_reduce_max(local_max, shared_float);

    if (isinf(max_val) && max_val > 0.0f) {
        unsigned int local_inf_count = 0u;
        for (uint32_t i = threadIdx.x; i < dim_size; i += blockDim.x) {
            const float v = bf16_to_float(input, row_base + static_cast<size_t>(i) * static_cast<size_t>(inner_size));
            if (isinf(v) && v > 0.0f) {
                local_inf_count += 1u;
            }
        }
        const unsigned int inf_count = block_reduce_sum_u32(local_inf_count, shared_uint);
        const float value = inf_count == 0u ? 0.0f : 1.0f / static_cast<float>(inf_count);
        for (uint32_t i = threadIdx.x; i < dim_size; i += blockDim.x) {
            const float v = bf16_to_float(input, row_base + static_cast<size_t>(i) * static_cast<size_t>(inner_size));
            const float y = (isinf(v) && v > 0.0f) ? value : 0.0f;
            output[row_base + static_cast<size_t>(i) * static_cast<size_t>(inner_size)] = float_to_bf16(y);
        }
        return;
    }

    if (!isfinite(max_val)) {
        for (uint32_t i = threadIdx.x; i < dim_size; i += blockDim.x) {
            output[row_base + static_cast<size_t>(i) * static_cast<size_t>(inner_size)] = float_to_bf16(0.0f);
        }
        return;
    }

    float local_sum = 0.0f;
    for (uint32_t i = threadIdx.x; i < dim_size; i += blockDim.x) {
        const float v = bf16_to_float(input, row_base + static_cast<size_t>(i) * static_cast<size_t>(inner_size));
        const float e = isnan(v) ? 0.0f : expf(v - max_val);
        local_sum += e;
    }

    const float sum_exp = block_reduce_sum(local_sum, shared_float);

    if (!(sum_exp > 0.0f) || !isfinite(sum_exp)) {
        for (uint32_t i = threadIdx.x; i < dim_size; i += blockDim.x) {
            output[row_base + static_cast<size_t>(i) * static_cast<size_t>(inner_size)] = float_to_bf16(0.0f);
        }
        return;
    }

    const float inv_sum = 1.0f / sum_exp;
    for (uint32_t i = threadIdx.x; i < dim_size; i += blockDim.x) {
        const float v = bf16_to_float(input, row_base + static_cast<size_t>(i) * static_cast<size_t>(inner_size));
        const float e = isnan(v) ? 0.0f : expf(v - max_val);
        output[row_base + static_cast<size_t>(i) * static_cast<size_t>(inner_size)] = float_to_bf16(e * inv_sum);
    }
}

} 

extern "C" {

cudaError_t rmsnorm_forward_cuda(
    const void* input,
    const void* weight,
    void* output,
    size_t numel,
    size_t normalized_shape,
    float eps,
    cudaStream_t stream
) {
    if (input == nullptr || output == nullptr) {
        return cudaErrorInvalidValue;
    }
    if (!valid_eps(eps)) {
        return cudaErrorInvalidValue;
    }

    uint32_t n_rows = 0u;
    uint32_t normalized_shape_u32 = 0u;
    cudaError_t err = validate_norm_args(numel, normalized_shape, &n_rows, &normalized_shape_u32);
    if (err != cudaSuccess) {
        return err;
    }
    if (numel == 0) {
        return cudaSuccess;
    }

    const unsigned int block_size = choose_block_size(normalized_shape);
    err = validate_current_device_limits(static_cast<size_t>(n_rows), block_size);
    if (err != cudaSuccess) {
        return err;
    }

    (void)cudaGetLastError();

    rmsnorm_forward_kernel<<<n_rows, block_size, 0, stream>>>(
        static_cast<const __nv_bfloat16*>(input),
        static_cast<const __nv_bfloat16*>(weight),
        static_cast<__nv_bfloat16*>(output),
        n_rows,
        normalized_shape_u32,
        eps
    );

    return finalize_launch(stream);
}

cudaError_t rmsnorm_backward_cuda(
    const void* grad_output,
    const void* input,
    const void* weight,
    void* grad_input,
    void* grad_weight,
    size_t numel,
    size_t normalized_shape,
    float eps,
    cudaStream_t stream
) {
    if (grad_output == nullptr || input == nullptr || grad_input == nullptr) {
        return cudaErrorInvalidValue;
    }
    if (!valid_eps(eps)) {
        return cudaErrorInvalidValue;
    }

    uint32_t n_rows = 0u;
    uint32_t normalized_shape_u32 = 0u;
    cudaError_t err = validate_norm_args(numel, normalized_shape, &n_rows, &normalized_shape_u32);
    if (err != cudaSuccess) {
        return err;
    }
    if (numel == 0) {
        return cudaSuccess;
    }

    const unsigned int row_block_size = choose_block_size(normalized_shape);
    const unsigned int weight_block_size = choose_block_size(static_cast<size_t>(n_rows));

    err = validate_current_device_limits(static_cast<size_t>(n_rows), row_block_size);
    if (err != cudaSuccess) {
        return err;
    }
    if (grad_weight != nullptr) {
        err = validate_current_device_limits(static_cast<size_t>(normalized_shape_u32), weight_block_size);
        if (err != cudaSuccess) {
            return err;
        }
    }

    float* inv_rms = nullptr;
    err = cudaMalloc(reinterpret_cast<void**>(&inv_rms), static_cast<size_t>(n_rows) * sizeof(float));
    if (err != cudaSuccess) {
        return err;
    }

    float* grad_weight_fp32 = nullptr;
    if (grad_weight != nullptr) {
        err = cudaMalloc(reinterpret_cast<void**>(&grad_weight_fp32), static_cast<size_t>(normalized_shape_u32) * sizeof(float));
        if (err != cudaSuccess) {
            cudaFree(inv_rms);
            return err;
        }
        err = cudaMemsetAsync(grad_weight_fp32, 0, static_cast<size_t>(normalized_shape_u32) * sizeof(float), stream);
        if (err != cudaSuccess) {
            cudaFree(grad_weight_fp32);
            cudaFree(inv_rms);
            return err;
        }
    }

    (void)cudaGetLastError();

    rmsnorm_stats_kernel<<<n_rows, row_block_size, 0, stream>>>(
        static_cast<const __nv_bfloat16*>(input),
        inv_rms,
        n_rows,
        normalized_shape_u32,
        eps
    );
    err = cudaPeekAtLastError();
    if (err != cudaSuccess) {
        if (grad_weight_fp32 != nullptr) {
            cudaFree(grad_weight_fp32);
        }
        cudaFree(inv_rms);
        return err;
    }

    rmsnorm_backward_input_kernel<<<n_rows, row_block_size, 0, stream>>>(
        static_cast<const __nv_bfloat16*>(grad_output),
        static_cast<const __nv_bfloat16*>(input),
        static_cast<const __nv_bfloat16*>(weight),
        inv_rms,
        static_cast<__nv_bfloat16*>(grad_input),
        n_rows,
        normalized_shape_u32
    );
    err = cudaPeekAtLastError();
    if (err != cudaSuccess) {
        if (grad_weight_fp32 != nullptr) {
            cudaFree(grad_weight_fp32);
        }
        cudaFree(inv_rms);
        return err;
    }

    if (grad_weight_fp32 != nullptr) {
        rmsnorm_backward_weight_kernel<<<normalized_shape_u32, weight_block_size, 0, stream>>>(
            static_cast<const __nv_bfloat16*>(grad_output),
            static_cast<const __nv_bfloat16*>(input),
            inv_rms,
            grad_weight_fp32,
            n_rows,
            normalized_shape_u32
        );
        err = cudaPeekAtLastError();
        if (err != cudaSuccess) {
            cudaFree(grad_weight_fp32);
            cudaFree(inv_rms);
            return err;
        }

        const uint32_t cast_numel = normalized_shape_u32;
        const unsigned int cast_block_size = kMaxBlockSize;
        const size_t cast_grid = static_cast<size_t>(cast_numel) / static_cast<size_t>(cast_block_size) + static_cast<size_t>(cast_numel % cast_block_size != 0u);

        err = validate_current_device_limits(cast_grid, cast_block_size);
        if (err != cudaSuccess) {
            cudaFree(grad_weight_fp32);
            cudaFree(inv_rms);
            return err;
        }

        float_to_bfloat16_kernel<<<static_cast<unsigned int>(cast_grid), cast_block_size, 0, stream>>>(
            grad_weight_fp32,
            static_cast<__nv_bfloat16*>(grad_weight),
            cast_numel
        );
        err = cudaPeekAtLastError();
        if (err != cudaSuccess) {
            cudaFree(grad_weight_fp32);
            cudaFree(inv_rms);
            return err;
        }
    }

    err = cudaStreamSynchronize(stream);
    const cudaError_t free_err_inv = cudaFree(inv_rms);
    const cudaError_t free_err_w = grad_weight_fp32 != nullptr ? cudaFree(grad_weight_fp32) : cudaSuccess;

    if (err != cudaSuccess) {
        return err;
    }
    if (free_err_inv != cudaSuccess) {
        return free_err_inv;
    }
    if (free_err_w != cudaSuccess) {
        return free_err_w;
    }
    return cudaSuccess;
}

cudaError_t layernorm_forward_cuda(
    const void* input,
    const void* weight,
    const void* bias,
    void* output,
    size_t numel,
    size_t normalized_shape,
    float eps,
    cudaStream_t stream
) {
    if (input == nullptr || output == nullptr) {
        return cudaErrorInvalidValue;
    }
    if (!valid_eps(eps)) {
        return cudaErrorInvalidValue;
    }

    uint32_t n_rows = 0u;
    uint32_t normalized_shape_u32 = 0u;
    cudaError_t err = validate_norm_args(numel, normalized_shape, &n_rows, &normalized_shape_u32);
    if (err != cudaSuccess) {
        return err;
    }
    if (numel == 0) {
        return cudaSuccess;
    }

    const unsigned int block_size = choose_block_size(normalized_shape);
    err = validate_current_device_limits(static_cast<size_t>(n_rows), block_size);
    if (err != cudaSuccess) {
        return err;
    }

    (void)cudaGetLastError();

    layernorm_forward_kernel<<<n_rows, block_size, 0, stream>>>(
        static_cast<const __nv_bfloat16*>(input),
        static_cast<const __nv_bfloat16*>(weight),
        static_cast<const __nv_bfloat16*>(bias),
        static_cast<__nv_bfloat16*>(output),
        n_rows,
        normalized_shape_u32,
        eps
    );

    return finalize_launch(stream);
}

cudaError_t gelu_forward_cuda(
    const void* input,
    void* output,
    size_t numel,
    bool approximate,
    cudaStream_t stream
) {
    if (numel == 0) {
        return cudaSuccess;
    }
    if (input == nullptr || output == nullptr) {
        return cudaErrorInvalidValue;
    }

    uint32_t numel_u32 = 0u;
    cudaError_t err = validate_linear_numel(numel, &numel_u32);
    if (err != cudaSuccess) {
        return err;
    }

    const unsigned int block_size = kMaxBlockSize;
    const size_t num_blocks = static_cast<size_t>(numel_u32) / static_cast<size_t>(block_size) + static_cast<size_t>(numel_u32 % block_size != 0u);

    err = validate_current_device_limits(num_blocks, block_size);
    if (err != cudaSuccess) {
        return err;
    }

    (void)cudaGetLastError();

    gelu_forward_kernel<<<static_cast<unsigned int>(num_blocks), block_size, 0, stream>>>(
        static_cast<const __nv_bfloat16*>(input),
        static_cast<__nv_bfloat16*>(output),
        numel_u32,
        approximate
    );

    return finalize_launch(stream);
}

cudaError_t gelu_backward_cuda(
    const void* grad_output,
    const void* input,
    void* grad_input,
    size_t numel,
    bool approximate,
    cudaStream_t stream
) {
    if (numel == 0) {
        return cudaSuccess;
    }
    if (grad_output == nullptr || input == nullptr || grad_input == nullptr) {
        return cudaErrorInvalidValue;
    }

    uint32_t numel_u32 = 0u;
    cudaError_t err = validate_linear_numel(numel, &numel_u32);
    if (err != cudaSuccess) {
        return err;
    }

    const unsigned int block_size = kMaxBlockSize;
    const size_t num_blocks = static_cast<size_t>(numel_u32) / static_cast<size_t>(block_size) + static_cast<size_t>(numel_u32 % block_size != 0u);

    err = validate_current_device_limits(num_blocks, block_size);
    if (err != cudaSuccess) {
        return err;
    }

    (void)cudaGetLastError();

    gelu_backward_kernel<<<static_cast<unsigned int>(num_blocks), block_size, 0, stream>>>(
        static_cast<const __nv_bfloat16*>(grad_output),
        static_cast<const __nv_bfloat16*>(input),
        static_cast<__nv_bfloat16*>(grad_input),
        numel_u32,
        approximate
    );

    return finalize_launch(stream);
}

cudaError_t softmax_forward_cuda(
    const void* input,
    void* output,
    size_t outer_size,
    size_t dim_size,
    size_t inner_size,
    cudaStream_t stream
) {
    uint32_t outer_u32 = 0u;
    uint32_t dim_u32 = 0u;
    uint32_t inner_u32 = 0u;
    size_t num_blocks = 0;
    cudaError_t err = validate_softmax_args(
        outer_size,
        dim_size,
        inner_size,
        &outer_u32,
        &dim_u32,
        &inner_u32,
        &num_blocks
    );
    if (err != cudaSuccess) {
        return err;
    }
    if (num_blocks == 0) {
        return cudaSuccess;
    }
    if (input == nullptr || output == nullptr) {
        return cudaErrorInvalidValue;
    }

    const unsigned int block_size = choose_block_size(dim_size);
    err = validate_current_device_limits(num_blocks, block_size);
    if (err != cudaSuccess) {
        return err;
    }

    (void)cudaGetLastError();

    softmax_forward_kernel<<<static_cast<unsigned int>(num_blocks), block_size, 0, stream>>>(
        static_cast<const __nv_bfloat16*>(input),
        static_cast<__nv_bfloat16*>(output),
        outer_u32,
        dim_u32,
        inner_u32
    );

    return finalize_launch(stream);
}

