import Mathlib

open scoped BigOperators

noncomputable section

namespace NormalizationActivationKernels

def sqMean {n : ℕ} (x : Fin n → ℝ) : ℝ := (∑ i, (x i) ^ 2) / (n : ℝ)

def rmsInv {n : ℕ} (eps : ℝ) (x : Fin n → ℝ) : ℝ := (sqMean x + eps) ^ (-(1 : ℝ) / 2)

def rmsDot {n : ℕ} (g w x : Fin n → ℝ) : ℝ := ∑ i, g i * w i * x i

def rmsBackward {n : ℕ} (eps : ℝ) (g w x : Fin n → ℝ) (i : Fin n) : ℝ :=
  g i * w i * rmsInv eps x - x i * (rmsDot g w x / (n : ℝ)) * (rmsInv eps x) ^ 3

def mean {n : ℕ} (x : Fin n → ℝ) : ℝ := (∑ i, x i) / (n : ℝ)

def centered {n : ℕ} (x : Fin n → ℝ) (i : Fin n) : ℝ := x i - mean x

def shiftedExp {n : ℕ} (z : Fin n → ℝ) (m : ℝ) (i : Fin n) : ℝ := Real.exp (z i - m)

def softmaxDenom {n : ℕ} (z : Fin n → ℝ) (m : ℝ) : ℝ := ∑ i, shiftedExp z m i

def softmax {n : ℕ} (z : Fin n → ℝ) (m : ℝ) (i : Fin n) : ℝ := shiftedExp z m i / softmaxDenom z m

theorem sqMean_nonneg {n : ℕ} (x : Fin n → ℝ) : 0 ≤ sqMean x := by
  unfold sqMean
  refine div_nonneg ?_ ?_
  · refine Finset.sum_nonneg ?_
    intro i hi
    positivity
  · positivity

theorem rms_backward_rewrite {n : ℕ} (eps : ℝ) (g w x : Fin n → ℝ) (i : Fin n) :
    rmsBackward eps g w x i =
      g i * w i * rmsInv eps x - x i * rmsDot g w x * (rmsInv eps x) ^ 3 / (n : ℝ) := by
  unfold rmsBackward
  ring

theorem centered_sum_rewrite {n : ℕ} (x : Fin n → ℝ) :
    (∑ i, centered x i) = (∑ i, x i) - (n : ℝ) * mean x := by
  unfold centered mean
  rw [Finset.sum_sub_distrib]
  simp [Finset.sum_const, nsmul_eq_mul]

theorem centered_sum_zero {n : ℕ} (h : 0 < n) (x : Fin n → ℝ) :
    (∑ i, centered x i) = 0 := by
  rw [centered_sum_rewrite]
  unfold mean
  have hn : (n : ℝ) ≠ 0 := by
    exact_mod_cast Nat.ne_of_gt h
  field_simp [hn]

theorem shiftedExp_pos {n : ℕ} (z : Fin n → ℝ) (m : ℝ) (i : Fin n) : 0 < shiftedExp z m i := by
  unfold shiftedExp
  exact Real.exp_pos _

theorem softmaxDenom_pos {n : ℕ} (h : 0 < n) (z : Fin n → ℝ) (m : ℝ) :
    0 < softmaxDenom z m := by
  let i : Fin n := ⟨0, h⟩
  have hi : i ∈ (Finset.univ : Finset (Fin n)) := by
    simp
  have hterm : 0 < shiftedExp z m i := shiftedExp_pos z m i
  have hle : shiftedExp z m i ≤ softmaxDenom z m := by
    unfold softmaxDenom
    exact Finset.single_le_sum (fun j hj => le_of_lt (shiftedExp_pos z m j)) hi
  exact lt_of_lt_of_le hterm hle

theorem softmax_nonneg {n : ℕ} (z : Fin n → ℝ) (m : ℝ) (i : Fin n) (h : 0 ≤ softmaxDenom z m) :
    0 ≤ softmax z m i := by
  unfold softmax
  exact div_nonneg (le_of_lt (shiftedExp_pos z m i)) h

theorem softmax_sum_one {n : ℕ} (h : 0 < n) (z : Fin n → ℝ) (m : ℝ) :
    (∑ i, softmax z m i) = 1 := by
  have hd : softmaxDenom z m ≠ 0 := ne_of_gt (softmaxDenom_pos h z m)
  calc
    (∑ i, softmax z m i)
        = ∑ i, shiftedExp z m i / softmaxDenom z m := by
            rfl
    _ = ∑ i, shiftedExp z m i * (softmaxDenom z m)⁻¹ := by
          simp [div_eq_mul_inv]
    _ = (∑ i, shiftedExp z m i) * (softmaxDenom z m)⁻¹ := by
          rw [Finset.sum_mul]
    _ = 1 := by
          unfold softmaxDenom
          field_simp [hd]

end NormalizationActivationKernels
